  /** Arcade rolling model: constant deceleration while the ball hugs the surface. */
  private applyRollingResistance(dt: number): void {
    const ball = this.ball;
    if (!ball) return;
    const velocity = ball.velocity;
    if (Math.abs(velocity.y) > AIRBORNE_SPEED) return;
    const horizontal = Math.hypot(velocity.x, velocity.z);
    if (horizontal <= 1e-4) return;
    const deceleration = this.runtime?.decelerationAt(ball.position) ?? 3.4;
    const factor = Math.max(0, horizontal - deceleration * dt) / horizontal;
    ball.body.setLinvel({ x: velocity.x * factor, y: velocity.y, z: velocity.z * factor }, true);
  }

  private updateCamera(dt: number): void {
    if (this.match.phase === 'simulating' || this.match.phase === 'hole-intro') {
      const focus = this.ballPosition();
      this.cameraController.setTarget({ x: focus.x, y: focus.y + 0.35, z: focus.z });
    }
    const state = this.cameraController.update(dt, this.cameraView());
    if (this.options.input.wasPressed('camera-reset')) {
      this.focusCamera(this.ballPosition());
    }
    const pose = this.cameraController.state;
    const camera = this.options.camera;
    camera.position.set(pose.position.x, pose.position.y, pose.position.z);
    camera.lookAt(state.target.x, state.target.y, state.target.z);
  }

  private focusCamera(position: Vec3): void {
    const dx = this.hole.cup.position.x - position.x;
    const dz = this.hole.cup.position.z - position.z;
    const yaw = Math.abs(dx) + Math.abs(dz) < 1e-5 ? Math.PI : Math.atan2(-dx, -dz);
    this.cameraController.reset({ x: position.x, y: position.y + 0.35, z: position.z });
    this.cameraController.setOrbit(yaw, CAMERA_PITCH, CAMERA_DISTANCE);
  }

  private syncMeshes(): void {
    for (const [playerId, mesh] of this.ballMeshes) {
      const completed = this.scoreOf(playerId)?.completed === true;
      const live = playerId === this.turnPlayerId && this.ball;
      const position = live ? this.ball.position : this.playerPositions.get(playerId);
      if (position) mesh.position.set(position.x, position.y, position.z);
      if (live && this.ball) {
        const rotation = this.ball.body.rotation();
        mesh.quaternion.set(rotation.x, rotation.y, rotation.z, rotation.w);
      }
      mesh.visible = !completed;
    }
  }

  private updatePresentation(dt: number): void {
    const input = this.options.input;
    this.minimapClock += dt;
    if (this.minimapClock >= MINIMAP_INTERVAL) {
      this.minimapClock = 0;
      this.minimap.render(buildMinimapModel(this.hole, this.ballPosition()));
    }
    if (this.toastClock > 0) {
      this.toastClock -= dt;
      if (this.toastClock <= 0) this.toastElement.hidden = true;
    }

    const humanTurn = this.isHumanTurn();
    this.hud.render({
      holeNumber: this.holeIndex + 1,
      holeCount: this.course.holes.length,
      holeName: this.hole.name,
      par: this.hole.par,
      strokes: this.scoreOf(this.turnPlayerId ?? '')?.strokes ?? 0,
      power: this.aimPower,
      canShoot: humanTurn && this.match.phase === 'aiming' && (this.ball?.canShoot ?? false),
      statusText: this.statusLine(),
    });
    this.hint.hidden = this.match.phase === 'match-results' || this.paused;

    const scoreboardVisible =
      !this.results.element.hidden === false &&
      (input.isDown('scoreboard') || this.introClock < 0 || this.paused);
    this.scoreboard.element.hidden = !scoreboardVisible;
    if (scoreboardVisible) {
      this.scoreboard.render({
        players: this.uiPlayers(),
        holeNumber: this.holeIndex + 1,
        holeCount: this.course.holes.length,
      });
    }
  }

  private showAim(direction: Vec3, power: number): void {
    const ball = this.ball;
    if (!ball) return;
    const position = ball.position;
    this.aimArrow.visible = true;
    this.aimArrow.position.set(position.x, position.y + 0.02, position.z);
    this.aimArrow.rotation.set(0, Math.atan2(direction.x, direction.z), 0);
    const length = 0.85 + clamp(power, 0, 1) * 3.4;
    this.aimArrow.scale.set(1, 1, length);
    this.aimMaterial.color.setHex(power > 0.86 ? 0xffbd59 : 0x8cf2c2);
  }

  private showResults(): void {
    const standings = this.scoreManager.standings(this.match.players);
    const profiles: PlayerProfile[] = this.match.players.map((player) => ({
      id: player.id,
      displayName: player.displayName,
      kind: player.kind,
      ballStyleId: player.ballStyleId,
      rating: player.rating,
    }));
    const changes = computeMatchRatings(participantsFromStandings(standings, profiles));
    const rows = this.uiPlayers();
    const coursePar = this.course.holes.reduce((sum, hole) => sum + hole.par, 0);
    const finishedAt = this.match.finishedAt ?? Date.now();
    const durationSeconds = Math.max(0, Math.round((finishedAt - (this.match.startedAt ?? finishedAt)) / 1000));
    const players: MatchResultPlayer[] = [];

    for (const standing of standings) {
      const row = rows.find((entry) => entry.id === standing.playerId);
      if (!row) continue;
      const player = this.match.players.find((entry) => entry.id === standing.playerId);
      const holeScores = player?.holeScores ?? [];
      const change = changes.find((entry) => entry.playerId === standing.playerId);
      const reward = calculateMatchReward({
        rank: standing.rank,
        playerCount: this.match.players.length,
        holesPlayed: this.course.holes.length,
        holesCompleted: holeScores.filter((score) => score.completed).length,
        totalStrokes: standing.totalStrokes,
        coursePar,
        holesInOne: holeScores.filter((score) => score.completed && score.strokes === 1).length,
        birdies: holeScores.filter((score) => score.completed && score.strokes === this.parOf(score.holeId) - 1).length,
        durationSeconds,
      });
      players.push({
        ...row,
        rank: standing.rank,
        ratingBefore: change?.ratingBefore,
        ratingAfter: change?.ratingAfter,
        xpEarned: reward.xp,
      });
    }

    this.results.render({
      players,
      courseName: this.course.name,
      holesPlayed: this.course.holes.length,
    });
    this.results.element.append(this.exitButton);
    this.results.element.hidden = false;
    this.scoreboard.element.hidden = true;
    this.aimArrow.visible = false;
    this.statusText = undefined;
  }

  private togglePause(): void {
    if (this.match.phase === 'paused') {
      this.match = this.matchManager.resume(this.match);
      this.paused = false;
    } else if (this.match.phase === 'aiming' || this.match.phase === 'simulating') {
      this.match = this.matchManager.pause(this.match);
      this.paused = true;
      this.aim.cancel();
      this.aimPower = 0;
    } else {
      return;
    }
    this.pauseOverlay.element.hidden = !this.paused;
  }

  private exit(): void {
    this.options.onExit?.();
  }

  private inputView(): InputSnapshot {
    return this.options.input;
  }

  /** Camera orbit ignores pointer motion while a shot is being charged. */
  private cameraView(): InputSnapshot {
    const input = this.options.input;
    if (!this.aim.isCharging && !this.paused) return input;
    const pointer: PointerSnapshot = { ...input.pointer, deltaX: 0, deltaY: 0, wheel: 0 };
    return {
      pointer,
      isDown: (action) => input.isDown(action),
      wasPressed: (action) => input.wasPressed(action),
      wasReleased: (action) => input.wasReleased(action),
    };
  }

  private uiPlayers(): UiPlayer[] {
    return this.match.players.map((player, index) => {
      const holeScore = player.holeScores.find((score) => score.holeId === this.hole.id);
      const totalStrokes = player.holeScores.reduce((sum, score) => sum + score.strokes, 0);
      const parPlayed = player.holeScores.reduce((sum, score) => sum + this.parOf(score.holeId), 0);
      const status: UiPlayerStatus = holeScore?.completed
        ? 'finished'
        : player.id === this.match.activePlayerId
          ? 'playing'
          : 'waiting';
      return {
        id: player.id,
        name: player.displayName,
        color: this.colorOf(player.id, index),
        strokes: holeScore?.strokes ?? 0,
        totalStrokes,
        parDelta: totalStrokes - parPlayed,
        status,
        isLocal: player.kind === 'human',
      };
    });
  }

  private statusLine(): string {
    if (this.paused) return 'PAUSED';
    if (this.match.phase === 'match-results') return 'MATCH COMPLETE';
    if (this.match.phase === 'hole-intro') return this.introClock < 0 ? 'HOLE COMPLETE' : 'GET READY';
    if (this.statusText) return this.statusText.toUpperCase();
    if (this.match.phase === 'simulating') return 'BALL IN MOTION';
    const name = this.nameOf(this.turnPlayerId).toUpperCase();
    return this.isHumanTurn() ? name + ' · READY' : name + ' · TURN';
  }

  private hintText(): string {
    const shot =
      this.aim.controlScheme === 'drag-power'
        ? 'LMB drag back to aim and load power, release to putt'
        : 'Hold LMB or SPACE to charge, release to putt';
    return 'Move mouse to orbit · ' + shot + ' · WASD pan · wheel zoom · R recentre · TAB scores · ESC pause';
  }

  private toast(text: string): void {
    this.toastElement.textContent = text;
    this.toastElement.hidden = false;
    this.toastClock = TOAST_SECONDS;
  }

  private ballPosition(): Vec3 {
    if (this.turnPlayerId && this.ball) return this.ball.position;
    return this.playerPositions.get(this.turnPlayerId ?? '') ?? this.hole.spawn;
  }

  private isHumanTurn(): boolean {
    const playerId = this.turnPlayerId;
    return playerId !== undefined && !this.botProfiles.has(playerId);
  }

  private scoreOf(playerId: string): PlayerHoleScore | undefined {
    return this.match.players
      .find((player) => player.id === playerId)
      ?.holeScores.find((score) => score.holeId === this.hole.id);
  }

  private parOf(holeId: string): number {
    return this.course.holes.find((hole) => hole.id === holeId)?.par ?? 0;
  }

  private nameOf(playerId: string | undefined): string {
    return this.match.players.find((player) => player.id === playerId)?.displayName ?? 'Player';
  }

  private colorOf(playerId: string, index: number): string {
    const player = this.match.players.find((entry) => entry.id === playerId);
    const style = player ? ballStyleById(player.ballStyleId) : undefined;
    if (player?.kind === 'human' && style && style.id !== DEFAULT_BALL_ID) return style.color;
    return PLAYER_COLORS[index % PLAYER_COLORS.length] ?? '#ffffff';
  }

  private disposeBall(): void {
    if (!this.ball) return;
    this.physics.world.removeRigidBody(this.ball.body);
    this.ball = undefined;
  }
}
